bool AnimationGraphRootMotionController3D::CanCommit(const AnimationGraphRootMotionControllerTransaction3D& transaction,const AnimationPose3D& pose)const noexcept{return pending_&&transaction.valid&&transaction.owner==reinterpret_cast<std::uintptr_t>(this)&&transaction.generation==generation_&&transaction.serial==serial_&&transaction.graph==pendingGraph_&&transaction.controller==pendingController_&&transaction.pose==&pose&&transaction.pose==pendingPose_&&transaction.sealedHash==pendingSeal_&&Seal(transaction)==pendingSeal_&&pendingGraph_&&pendingController_&&pendingGraph_->CanCommitRootMotionPreview(pendingGraphToken_,pose)&&pendingController_->CanCommitDirectDisplacementPreview(pendingControllerToken_);}
bool AnimationGraphRootMotionController3D::Commit(AnimationGraphRootMotionControllerTransaction3D& transaction,AnimationPose3D& pose,AnimationGraphRootMotionControllerResult3D* output)noexcept{if(ConsumeFailure(AnimationGraphRootMotionControllerFailureCheckpoint3D::BeforeCommitValidation)||!CanCommit(transaction,pose)){Cancel(transaction);return false;}if(ConsumeFailure(AnimationGraphRootMotionControllerFailureCheckpoint3D::AfterDualCanCommit)){Cancel(transaction);return false;}const auto result=pendingResult_;pendingGraph_->CommitRootMotionPreviewUnchecked(pendingGraphToken_,pose);pendingController_->CommitDirectDisplacementPreviewUnchecked(pendingControllerToken_);pending_=false;++generation_;transaction={};if(output)*output=result;return true;}
bool AnimationGraphRootMotionController3D::Cancel(AnimationGraphRootMotionControllerTransaction3D& transaction)noexcept{if(!pending_||!transaction.valid||transaction.owner!=reinterpret_cast<std::uintptr_t>(this)||transaction.generation!=generation_||transaction.serial!=serial_)return false;if(pendingController_)pendingController_->CancelDirectDisplacementPreview(pendingControllerToken_);if(pendingGraph_)pendingGraph_->CancelRootMotionPreview(pendingGraphToken_);pending_=false;transaction={};return true;}
bool AnimationGraphRootMotionController3D::Reset(AnimationGraph3D& graph,CharacterController3D& controller,Vec3 feet,float yaw)noexcept{if(generation_==(std::numeric_limits<std::uint64_t>::max)()||!graph.CanResetRootMotion()||!controller.CanResetDirectDisplacement(feet,yaw))return false;if(pending_){pendingController_->CancelDirectDisplacementPreview(pendingControllerToken_);pendingGraph_->CancelRootMotionPreview(pendingGraphToken_);pending_=false;}controller.ResetDirectDisplacementUnchecked(feet,yaw);graph.ResetRootMotion();++generation_;return true;}
bool AnimationGraphRootMotionController3D::Teleport(AnimationGraph3D& graph,CharacterController3D& controller,Vec3 feet,float yaw,std::uint64_t previousTick)noexcept{if(generation_==(std::numeric_limits<std::uint64_t>::max)()||!graph.CanTeleportRootMotion(previousTick)||!controller.CanTeleportDirectDisplacement(feet,yaw,previousTick))return false;if(pending_){pendingController_->CancelDirectDisplacementPreview(pendingControllerToken_);pendingGraph_->CancelRootMotionPreview(pendingGraphToken_);pending_=false;}controller.TeleportDirectDisplacementUnchecked(feet,yaw,previousTick);graph.TeleportRootMotion(previousTick);++generation_;return true;}
